  "pill.detachTitle": "{name} — SSH-Host trennen",
  "pill.detachDesc1Pre": "Dies verwandelt",
  "pill.detachDesc1Mid": "wieder in ein reines lokales Projekt: seine lokale Arbeitskopie bleibt genau dort, wo sie ist, und wird wieder zum Projektverzeichnis. Die Dateien auf dem Remote-Host sind",
  "pill.detachDesc1Post": "betroffen, und nichts Lokales wird gelöscht.",
  "pill.detachDesc2Pre": "Was dabei wegfällt, ist die",
  "pill.pairingWord": "Kopplung",
  "pill.detachDesc2Post": ": Git-Gleichschritt stoppt, und der Auto-Sync-Bereich, den du für diesen Host gewählt hast — welche Ordner übertragen werden und der Datensatz dessen, was bereits im Gleichschritt war — wird verworfen. Den gleichen Host später erneut anzuhängen bedeutet, diesen Bereich von Grund auf neu festzulegen.",
  "pill.detaching": "Wird getrennt…",
  "pill.detachToLocal": "Zu lokal trennen",
  "pill.containerSettingsTitle": "{name} — Container-Einstellungen",
  "pill.containerScopeRestartNote": "Eine Änderung startet die Tabs neu, die die Grenze wechseln — eine laufende Shell oder ein Skript wird unterbrochen. Agenten-Tabs sind in beiden Fällen nicht betroffen.",
  "pill.containerScopeLegend": "Was im Container läuft",
  "pill.containerScopeAll": "Alles in diesem Projekt",
  "pill.containerScopeAllHelp": "Agenten-Tabs, Shells, Skripte und Ausführen/Debuggen im Viewer. Nichts aus diesem Projekt erreicht den Rest deines Rechners.",
  "pill.containerScopeAgents": "Nur Agenten-Tabs",
  "pill.containerScopeAgentsHelp": "Shells, Skripte und Ausführen/Debuggen bleiben auf dem Host, mit deiner Host-Toolchain — eine .venv-, conda- oder pyenv-Umgebung funktioniert wieder, weil ihr Interpreter auf dem Host liegt und nicht im Image.",
  "pill.containerScopeAgentsCaveat": "Der Agent schreibt weiterhin in den Projektordner, ein von ihm geschriebenes Skript ist also einen Ausführen-Klick von deinem ganzen Rechner entfernt. Diesen Schritt kann er nicht selbst gehen — keine Datei im Projekt wird als Startbefehl zurückgelesen — aber lies, was du ausführst. Für Code, den du für bösartig und nicht bloß ungeprüft hältst, ist ein Container die falsche Stufe.",
  "pill.containerAppliedNote": "Wird beim nächsten Containerstart angewendet (Projektaktivierung oder Tab-Erzeugung) — ein laufender Container mit geänderten Einstellungen wird automatisch ersetzt.",
  "pill.buildFromDockerfile": "Aus einem Dockerfile in diesem Projekt bauen",
