  "pill.networkNotePre": "Hinweis: Die Standard-Bridge erreicht weiterhin Dienste, die an diesen Rechner gebunden sind (Ollama, Dev-Server), über die Docker-Gateway-IP. Vollständig geschlossen bedeutet",
  "pill.networkNotePost": "oder ein benutzerdefiniertes Allowlist-Netzwerk.",
