  "remoteMachines.saveTitleTerminal": "Eine Terminal-Anmeldung sieht Eldrun nie, daher wird nichts Neues gespeichert — und auch nichts gelöscht. Ein gespeichertes Passwort bleibt unverändert; im eigenen Connect-Menü der Maschine kannst du es ändern.",
  "remoteMachines.saveTitleHeadless": "Speichert das SSH-Passwort dieser Maschine im Betriebssystem-Schlüsselbund, indiziert nach Host — das eigene Connect-Menü der Maschine findet es dann und fragt nicht erneut. Standardmäßig aus; ein Abwählen löscht ein zuvor gespeichertes Passwort.",
