  "remoteMachines.sharedFsToggleTitleStep2": "Aus (Standard): Diese Maschine teilt sich den Projektordner der primären Maschine über ein gemeinsames Dateisystem — keine Kopie, kein Git. An: Gib ihr eine eigene, einseitig synchronisierte Kopie des Codes (für Hosts, die keinen Speicher teilen).",
  "remoteMachines.syncCopyDescOn": "Diese Maschine behält ihre eigene Kopie des Codes, einseitig von der primären Maschine synchronisiert. Navigiere zum (oder erstelle den) Ordner für diese Kopie.",
