  "hpcWizard.createProject": "Projekt erstellen",
  "hpcWizard.introPre": "Auf einem Cluster ist dein Home-Verzeichnis ein kleines, quotiertes Dateisystem, das für Code gedacht ist. Die Daten einer Berechnung gehören in einen",
