  "mail.keys.theirs": "Schlüssel anderer Personen",
  "mail.keys.noneYet": "Noch kein Schlüssel für {address}.",
  "mail.keys.noneTheirs": "Noch keine. Importiere einen zugesandten Schlüssel oder füge unten einen ein.",
  "mail.keys.generate": "Schlüssel erstellen",
  "mail.keys.generateHint": "Erstellt einen Curve25519-Schlüssel für dieses Konto. Schicke die öffentliche Hälfte an alle, die dir verschlüsselt schreiben können sollen.",
  "mail.keys.ownKey": "dein Schlüssel",
  "mail.keys.boundTo": "verwendet für {label}",
  "mail.keys.useForAccount": "Für dieses Konto verwenden",
  "mail.keys.verifiedCheckbox": "Ich habe diesen Fingerabdruck mit dem Inhaber abgeglichen",
  "mail.keys.noIdentity": "(kein Name auf dem Schlüssel)",
  "mail.keys.export": "Herauskopieren",
  "mail.keys.exported": "Öffentlicher Schlüssel — {fp}",
  "mail.keys.exportedHint": "Das ist nur die öffentliche Hälfte. Gib sie beliebig weiter; damit kann man dir verschlüsselt schreiben und deine Signaturen prüfen. Dein privater Schlüssel wird nie exportiert.",
  "mail.keys.import": "Schlüssel hinzufügen",
  "mail.keys.importHint": "Füge einen zugesandten Schlüssel ein oder wähle eine Datei. Ein hinzugefügter Schlüssel gilt zunächst als ungeprüft — setze das Häkchen erst, wenn du den Fingerabdruck telefonisch oder persönlich mit dem Inhaber abgeglichen hast.",
  "mail.keys.importFile": "Aus einer Datei…",
  "mail.keys.importPasted": "Eingefügten Schlüssel hinzufügen",
  "mail.searchScanned": "Die neuesten {count} Nachrichten wurden durchsucht. Verschlüsselte Mail wird beim Durchsuchen entschlüsselt, ältere Nachrichten wurden daher nicht angesehen.",
  "mail.encryption.title": "Verschlüsselung der lokalen Mail",
  "mail.encryption.details": "Details",
  "mail.encryption.unlock": "Entsperren",
  "mail.encryption.unlockIntro": "Dieses Postfach ist mit einer Passphrase verschlüsselt. Gib sie ein, um die auf diesem Rechner gespeicherte Mail zu öffnen.",
  "mail.encryption.unlockDegraded": "Bis dahin siehst du ein vorläufiges Postfach: Mail lässt sich abrufen und lesen, es wird aber nichts gespeichert und alles ist weg, sobald Eldrun schließt.",
  "mail.encryption.passphrase": "Passphrase",
  "mail.encryption.passphraseConfirm": "Passphrase wiederholen",
  "mail.encryption.passphraseNoRecovery": "Diese Passphrase lässt sich nicht wiederherstellen. Wenn du sie vergisst, ist die hier gespeicherte Mail verloren — du müsstest sie löschen und neu herunterladen.",
  "mail.encryption.offerIntro": "Die Mail verschlüsseln, die Eldrun auf diesem Rechner ablegt, damit Nachrichten, Anhänge und Entwürfe ohne den Schlüssel unlesbar sind.",
  "mail.encryption.scopeHonest": "Was das wirklich schützt: Backups, Kopien, in die Cloud synchronisierte Ordner und Rechner, auf denen sich andere anmelden können. Es schützt nicht vor jemandem, der bei geöffnetem Eldrun Programme unter deinem Konto ausführen kann, und wenn deine Festplatte ohnehin verschlüsselt ist, bringt es beim gestohlenen Laptop wenig.",
  "mail.encryption.metadataHonest": "Weiterhin auf der Festplatte lesbar: wie viele Nachrichten es gibt, welche Ordner existieren sowie Datum, Größe und Gelesen-/Markiert-Status jeder Nachricht. Dafür braucht es Festplattenverschlüsselung, die auch Dateinamen verbirgt.",
  "mail.encryption.howToUnlock": "Art der Entsperrung",
  "mail.encryption.modeKeychain": "Systemschlüsselbund verwenden",
  "mail.encryption.modeKeychainHint": "Empfohlen. Dein Postfach öffnet sich ohne Nachfrage. Ist der Schlüsselbund einmal gesperrt, zeigt Eldrun ein vorläufiges Postfach statt gar nichts.",
  "mail.encryption.modeKeychainLocked": "Nicht verfügbar — der Systemschlüsselbund ist gesperrt oder auf diesem Rechner nicht vorhanden.",
  "mail.encryption.modePassphrase": "Nach einer Passphrase fragen",
  "mail.encryption.modePassphraseHint": "Einmal pro Sitzung eingetippt. Im Schlüsselbund wird nichts abgelegt.",
  "mail.encryption.migrationCaveat": "Hier ist bereits Mail gespeichert. Sie zu verschlüsseln schreibt die Datenbank neu und löscht die alte Kopie — auf einer SSD löscht das eine Datei aber nicht wirklich. Wenn dir das wichtig ist, nimm stattdessen Löschen und neu herunterladen.",
  "mail.encryption.enable": "Verschlüsseln",
  "mail.encryption.enableAndMigrate": "Vorhandene Mail verschlüsseln",
  "mail.encryption.notNow": "Nein danke",
  "mail.encryption.reset": "Löschen und neu herunterladen",
  "mail.encryption.resetHint": "Löscht die auf diesem Rechner gespeicherte Mail und legt einen verschlüsselten Speicher neu an. Langsamer, hinterlässt aber nie eine unverschlüsselte Kopie. Ungesendete Entwürfe gehen verloren; alles andere wird erneut vom Server geladen.",
  "mail.encryption.statusOn": "Die auf diesem Rechner gespeicherte Mail ist verschlüsselt.",
  "mail.encryption.statusOnButClosed": "Dieses Postfach ist verschlüsselt, die gespeicherte Mail ist aber gerade nicht geöffnet.",
  "mail.encryption.statusModeKeychain": "Wird automatisch aus dem Systemschlüsselbund entsperrt.",
  "mail.encryption.statusModePassphrase": "Wird mit einer Passphrase entsperrt, die du einmal pro Sitzung eingibst.",
  "mail.encryption.statusEphemeral": "Der Schlüssel konnte nicht gelesen werden, du siehst daher ein vorläufiges Postfach — es wird nichts gespeichert.",
  "mail.encryption.bannerEphemeral": "Mail wird nicht gespeichert: Der Verschlüsselungsschlüssel konnte nicht gelesen werden.",
